#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef long double ld;


const int N = 1005;


int n, x, leaf[N];
vector < int > g[N];

void dfs(int v, int pr = -1){
    bool isleaf = 1;
    for(auto to : g[v]){
        if(to != pr){
            isleaf = false;
            dfs(to, v);
        }
    }
    leaf[v] = isleaf;
}

void dfs1(int v, int pr = -1){
    int cur = 0;
    if(leaf[v]){
        return;
    }
    for(auto to : g[v]){
        if(to != pr){
            cur += leaf[to];
        }
    }
    if(cur < 3){
        cout << "No";
        exit(0);
    }
}
main(){
    ios_base::sync_with_stdio(0);cin.tie(0);cout.tie(0);
    cin >> n;
    for(int i = 1; i < n; i++){
        cin >> x;
        g[x].push_back(i + 1);
    }
    dfs(1);
    dfs1(1);
    cout << "Yes";
}

